#!/usr/bin/env python3
"""Generate complete regions.ts with all 31 PRC provinces (GB/T 2260)."""
import json, os

# Compact format: (code, name, [(code, name, [(code, name), ...]), ...])
# Municipalities (京/津/沪/渝): one-level city with same name as province
R = []

def p(code, name, cities):
    R.append({"code": code, "name": name, "children": cities})

def c(code, name, districts):
    return {"code": code, "name": name, "children": [{"code": d[0], "name": d[1]} for d in districts]}

def mc(code, name, districts):
    """Municipality city (name same as province)"""
    return {"code": code, "name": name, "children": [{"code": d[0], "name": d[1]} for d in districts]}

