# Summarize and write
def count_nodes(r):
    n = 1
    for c in r.get('children', []):
        n += count_nodes(c)
    return n

total = sum(count_nodes(r) for r in R)
print(f"Generated {len(R)} provinces, {total} nodes total")

os.makedirs('src/data', exist_ok=True)
with open('src/data/regions.ts', 'w', encoding='utf-8') as f:
    f.write('import type { RegionData } from \'@/types\'\n\n')
    f.write('export const regionData: RegionData[] = ')
    json.dump(R, f, ensure_ascii=False, indent=2)
    f.write('\n')

size = os.path.getsize('src/data/regions.ts')
print(f"Written regions.ts: {size:,} bytes")
